package org.eclipse.kura.core.keystore.crl.test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.security.cert.X509CRL;
import java.time.Instant;
import java.util.Collections;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

import org.junit.Test;

public class CrlManagerLifecycleTest extends CrlKeystoreServiceTestBase {

    private static final String STORE_THREAD_NAME = "CRLStore";
    private static final String UPDATE_THREAD_NAME = "CRLManager-update";
    private static final long THREAD_EXIT_TIMEOUT_MS = TimeUnit.SECONDS.toMillis(10);

    private final Map<String, Set<Thread>> threadsBeforeScenario = new HashMap<>();
    private X509CRL crl;

    @Test
    public void tenCrlOptionChangesLeaveNoStaleCrlManagerThread() throws Exception {
        givenThreadsAlreadyRunning();
        givenKeystoreServiceWithCrlManagement(Collections.emptyMap());
        givenCrl();

        whenCrlOptionChangesTenTimesWithAPendingStoreWrite();

        thenAtMostThreadsNamedAreRunning(STORE_THREAD_NAME, 1);
        thenAtMostThreadsNamedAreRunning(UPDATE_THREAD_NAME, 1);
    }

    @Test
    public void deactivationStopsCrlManagerThreads() throws Exception {
        givenThreadsAlreadyRunning();
        givenKeystoreServiceWithCrlManagement(Collections.emptyMap());
        givenCrl();
        givenCrlAddedToKeystore();

        whenKeystoreServiceIsDeactivated();

        thenAtMostThreadsNamedAreRunning(STORE_THREAD_NAME, 0);
        thenAtMostThreadsNamedAreRunning(UPDATE_THREAD_NAME, 0);
    }

    @Test
    public void crlAddedJustBeforeAnOptionChangeIsKept() throws Exception {
        givenKeystoreServiceWithCrlManagement(Collections.emptyMap());
        givenCrl();
        givenCrlAddedToKeystore();

        whenCrlOptionChanges("crl.check.interval", 6L);

        thenKeystoreServesCrls(1);
    }

    private void givenThreadsAlreadyRunning() {
        this.threadsBeforeScenario.put(STORE_THREAD_NAME, runningThreadsNamed(STORE_THREAD_NAME));
        this.threadsBeforeScenario.put(UPDATE_THREAD_NAME, runningThreadsNamed(UPDATE_THREAD_NAME));
    }

    private void givenCrl() throws Exception {
        this.crl = newCrl("cn=Test CA, dc=bar.com", Date.from(Instant.now().minusSeconds(60)),
                Date.from(Instant.now().plusSeconds(3600)));
    }

    private void givenCrlAddedToKeystore() throws Exception {
        this.keystoreService.addCRL(this.crl);
    }

    private void whenCrlOptionChangesTenTimesWithAPendingStoreWrite() throws Exception {
        for (long i = 1; i <= 10; i++) {
            this.keystoreService.addCRL(this.crl);
            whenCrlOptionChanges("crl.check.interval", 5L + i);
        }
    }

    private void thenAtMostThreadsNamedAreRunning(final String name, final int expectedMax)
            throws InterruptedException {
        final Set<Thread> before = this.threadsBeforeScenario.get(name);
        final long deadline = System.currentTimeMillis() + THREAD_EXIT_TIMEOUT_MS;

        Set<Thread> started = startedThreadsNamed(name, before);

        while (started.size() > expectedMax && System.currentTimeMillis() < deadline) {
            Thread.sleep(100);
            started = startedThreadsNamed(name, before);
        }

        assertTrue("threads named " + name + " still running: " + started, started.size() <= expectedMax);
    }

    private void thenKeystoreServesCrls(final int expectedCount) {
        assertEquals(expectedCount, this.keystoreService.getCRLs().size());
    }

    private static Set<Thread> startedThreadsNamed(final String name, final Set<Thread> before) {
        return runningThreadsNamed(name).stream().filter(t -> !before.contains(t)).collect(Collectors.toSet());
    }

    private static Set<Thread> runningThreadsNamed(final String name) {
        return Thread.getAllStackTraces().keySet().stream().filter(t -> t.isAlive() && name.equals(t.getName()))
                .collect(Collectors.toSet());
    }
}
